#!/usr/bin/env python3
"""Verify the self-signed TLS certificate used by the internal development server.

Checks that:
  * the certificate, key and combined PEM files all exist and are non-empty
  * the private key has 600 permissions
  * the certificate parses and loads together with its key
  * the combined PEM holds the same certificate plus the key
  * the certificate reports its Common Name and expiration date

Only the Python standard library (plus the `openssl` CLI) is required.
"""

import os
import ssl
import subprocess
import sys
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"
KEY_PATH = "/app/ssl/server.key"
PEM_PATH = "/app/ssl/server.pem"

DATE_FORMATS = ("%b %d %H:%M:%S %Y %Z", "%b %d %H:%M:%S %Y")


def fail(message):
    """Print an error message and exit with a non-zero status."""
    print("ERROR: %s" % message)
    sys.exit(1)


def openssl(*args):
    """Run an openssl subcommand and return its stdout."""
    try:
        result = subprocess.run(
            ["openssl", *args],
            capture_output=True,
            text=True,
            check=True,
        )
    except FileNotFoundError:
        fail("the 'openssl' executable was not found on PATH")
    except subprocess.CalledProcessError as exc:
        fail("openssl %s failed: %s" % (" ".join(args), (exc.stderr or "").strip() or exc))
    return result.stdout.strip()


def parse_openssl_date(value):
    """Parse an OpenSSL date such as 'Nov  4 10:25:47 2027 GMT'."""
    cleaned = " ".join(value.split())
    for fmt in DATE_FORMATS:
        try:
            parsed = datetime.strptime(cleaned, fmt)
        except ValueError:
            continue
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed
    fail("unable to parse certificate date: %r" % value)


def check_files_exist():
    for path in (CERT_PATH, KEY_PATH, PEM_PATH):
        if not os.path.isfile(path):
            fail("required file is missing: %s" % path)
        if os.path.getsize(path) == 0:
            fail("required file is empty: %s" % path)
    print("[ok] certificate file found: %s (%d bytes)" % (CERT_PATH, os.path.getsize(CERT_PATH)))


def check_key_permissions():
    mode = os.stat(KEY_PATH).st_mode & 0o777
    if mode != 0o600:
        fail("private key permissions are %o, expected 600" % mode)
    print("[ok] private key permissions are 600")


def check_cert_loads():
    """Confirm the certificate parses and matches the private key."""
    try:
        with open(CERT_PATH, "r", encoding="utf-8") as handle:
            pem_data = handle.read()
    except OSError as exc:
        fail("cannot read %s: %s" % (CERT_PATH, exc))

    if "-----BEGIN CERTIFICATE-----" not in pem_data:
        fail("%s is not a PEM encoded certificate" % CERT_PATH)

    try:
        der = ssl.PEM_cert_to_DER_cert(pem_data)
    except ValueError as exc:
        fail("certificate could not be decoded: %s" % exc)
    if not der:
        fail("certificate decoded to empty DER data")

    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    try:
        context.load_cert_chain(certfile=CERT_PATH, keyfile=KEY_PATH)
    except (ssl.SSLError, OSError) as exc:
        fail("certificate and key could not be loaded together: %s" % exc)

    print("[ok] certificate loaded successfully and matches %s" % KEY_PATH)
    return der


def extract_cert_block(text):
    """Return the first PEM certificate block contained in text, or None."""
    begin_marker = "-----BEGIN CERTIFICATE-----"
    end_marker = "-----END CERTIFICATE-----"
    begin = text.find(begin_marker)
    if begin == -1:
        return None
    end = text.find(end_marker, begin)
    if end == -1:
        return None
    return text[begin:end + len(end_marker)] + "\n"


def check_combined_pem(der):
    """Confirm the combined PEM holds both the key and the same certificate."""
    with open(PEM_PATH, "r", encoding="utf-8") as handle:
        combined = handle.read()

    has_key = (
        "[REDACTED PRIVATE KEY HEADER]" in combined
        or "[REDACTED PRIVATE KEY HEADER]" in combined
    )
    if not has_key:
        fail("%s does not contain a PEM private key" % PEM_PATH)

    cert_block = extract_cert_block(combined)
    if cert_block is None:
        fail("%s does not contain a complete PEM certificate" % PEM_PATH)

    try:
        combined_der = ssl.PEM_cert_to_DER_cert(cert_block)
    except ValueError as exc:
        fail("certificate block in %s could not be decoded: %s" % (PEM_PATH, exc))

    if combined_der != der:
        fail("%s does not contain the same certificate as %s" % (PEM_PATH, CERT_PATH))

    print("[ok] combined PEM contains the private key and certificate")


def get_common_name():
    """Read the Common Name from the certificate subject."""
    subject = openssl("x509", "-in", CERT_PATH, "-noout", "-subject")
    subject = subject.split("=", 1)[-1].strip() if subject.startswith("subject") else subject
    for rdn in subject.split(","):
        part = rdn.strip()
        if part.upper().startswith("CN="):
            return part[3:].strip(), subject
    fail("could not determine the Common Name from subject: %s" % subject)


def get_key_bits():
    """Report the certificate public key size in bits."""
    text = openssl("x509", "-in", CERT_PATH, "-noout", "-text")
    for line in text.splitlines():
        if "Public-Key:" in line:
            digits = "".join(ch for ch in line if ch.isdigit())
            if digits:
                return int(digits)
    return None


def report_details():
    common_name, subject = get_common_name()

    not_before = parse_openssl_date(
        openssl("x509", "-in", CERT_PATH, "-noout", "-startdate").split("=", 1)[-1]
    )
    not_after = parse_openssl_date(
        openssl("x509", "-in", CERT_PATH, "-noout", "-enddate").split("=", 1)[-1]
    )
    fingerprint = openssl("x509", "-in", CERT_PATH, "-noout", "-fingerprint", "-sha256").split("=", 1)[-1]
    bits = get_key_bits()

    print("")
    print("Certificate details")
    print("-------------------")
    print("%-15s %s" % ("Subject:", subject))
    print("%-15s %s" % ("Common Name:", common_name))
    print("%-15s %s" % ("Key size:", ("%s bits" % bits) if bits else "unknown"))
    print("%-15s %s" % ("Not before:", not_before.strftime("%Y-%m-%d")))
    print("%-15s %s" % ("Expiration:", not_after.strftime("%Y-%m-%d")))
    print("%-15s %s" % ("SHA-256:", fingerprint))
    print("")

    days_left = (not_after - datetime.now(timezone.utc)).days
    if days_left < 0:
        fail("certificate expired on %s" % not_after.strftime("%Y-%m-%d"))
    print("[ok] certificate is valid for %d more day(s)" % days_left)

    if bits is not None and bits != 2048:
        print("[warn] expected a 2048-bit RSA key, found %d bits" % bits)


def main():
    print("Verifying certificate at %s" % CERT_PATH)
    print("")
    check_files_exist()
    check_key_permissions()
    der = check_cert_loads()
    check_combined_pem(der)
    report_details()
    print("")
    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())
PYEOF
